const episodes = $input.all().filter(item => item.json.id);

if (episodes.length === 0) {
  throw new Error('No episodes with status audio_ready. Run WF-05 first.');
}

const ep = episodes[0].json;

return [{
  json: {
    episode_id: ep.id,
    title: ep.title,
    script: ep.script,
    audio_url: ep.audio_url,
    status: ep.status,
    created_at: ep.created_at
  }
}];

const ep = $json;
const pubDate = new Date(ep.created_at || Date.now()).toUTCString();
const description = (ep.script || '').substring(0, 500).replace(/[<>&]/g, '');

const rssItem = \`<item>
  <title>\${ep.title}</title>
  <description><![CDATA[\${description}...]]></description>
  <enclosure url="\${ep.audio_url}" length="0" type="audio/mpeg"/>
  <guid isPermaLink="false">\${ep.episode_id}</guid>
  <pubDate>\${pubDate}</pubDate>
  <itunes:duration>300</itunes:duration>
  <itunes:summary>\${description}...</itunes:summary>
</item>\`;

return [{
  json: {
    ...ep,
    rss_item: rssItem,
    description: description
  }
}];

